(()=>{let u=location.pathname.split("/").filter(Boolean).pop();if(!["american-west","ww1","medicine","elizabethan"].includes(u))return;let row=document.querySelector(".walkthrough-strip .chip-row");if(!row)return;[2025,2026].forEach(y=>{if([...row.querySelectorAll("a")].some(a=>a.textContent.trim()===String(y)))return;let a=document.createElement("a");a.className="year-chip",a.href=`${y===2025?"paper-2025/":"paper-2026/"}`,a.textContent=y,row.append(a)})})();
